verbalization_templates.po_template:
SELECT distinct ?p ?o ?oLabel
WHERE {{
  BIND(wd:{entity} AS ?s) .

  ?s ?p ?o .
  FILTER(?p != wd:P18)
  FILTER NOT EXISTS {{ ?o a ontolex:LexicalSense }}
  ?prop wikibase:directClaim ?p .
  OPTIONAL {{
    ?o rdfs:label ?oLabel .
    FILTER (LANG(?oLabel) = "en")
  }}
}} LIMIT 1000

